'use strict';
const LIVE=(DATA.meta&&DATA.meta.live)||null, LIVE_STATUS=(DATA.meta&&DATA.meta.liveStatus)||'demo';
const BCP_FONT='Flexo,Arial,sans-serif';
const MON=DATA.monitor, MODEL=new Map(MON.models.map(m=>[m.id,m])), PROJECT=new Map(MON.projects.map(p=>[p.id,p]));
const originals={renderRecs,renderBI,renderBIContent};
const M={route:'dashboard',project:'all',period:'30',models:new Set(MON.models.map(m=>m.id)),query:'',page:1,sort:'som',dir:-1,prompt:'all',referenceMetric:'mentions',intent:'all',sourcesBCP:false};
const SOV_TIP='Visibilidad de BCP frente a la competencia. Pondera posición, prominencia y contexto (positivo/neutral) de cada banco en la respuesta.';
MON.metricDefinitions.som=SOV_TIP;
MON.metricDefinitions.mentionRate='Respuestas válidas con mención de BCP ÷ respuestas válidas × 100. Se excluyen las respuestas con error. Variación en puntos porcentuales.';
MON.metricDefinitions.position='Posición promedio de BCP en las respuestas válidas donde fue mencionado y tiene posición disponible. Menor es mejor.';
const observationMap=new Map(MON.observations.map(o=>[o.id,o]));
const engineBadge=(id,compact=false)=>{const m=MODEL.get(id);return `<span class="engine-badge ${compact?'compact':''}" title="${esc(m.name+' · '+m.vendor)}"><span class="engine-symbol" style="color:${m.color};background:${m.color}14">${m.icon}</span>${esc(m.short||m.name)}</span>`};
const engineIcons=()=>[...M.models].map(id=>{const m=MODEL.get(id);return `<span class="engine-symbol" title="${esc(m.name)}" style="color:${m.color};background:${m.color}14">${m.icon}</span>`}).join('');
const fmt=(v,d=1)=>v===null||v===undefined?'—':Number(v).toLocaleString('es-PE',{maximumFractionDigits:d,minimumFractionDigits:d});
function bounds(previous=false){const end=new Date(MON.referenceDate+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);const days=Number(M.period)||30;if(previous)end.setUTCDate(end.getUTCDate()-days);const start=new Date(end);start.setUTCDate(start.getUTCDate()-days);return [start.toISOString().slice(0,10),end.toISOString().slice(0,10)]}
function observations({previous=false,project=M.project,prompt=M.prompt}={}){const [start,end]=bounds(previous);return MON.observations.filter(o=>M.models.has(o.modelId)&&(project==='all'||o.projectId===project)&&(prompt==='all'||o.promptId===prompt)&&(M.period==='source'?(!previous&&!o.isExample):o.date>=start&&o.date<end))}
function voice(o){return o.status==='error'?null:Number.isFinite(o.sov)?o.sov:Number.isFinite(o.som)?o.som:null}
function average(values){const available=values.filter(Number.isFinite);return available.length?available.reduce((sum,value)=>sum+value,0)/available.length:null}
function summary(rows){
 const ok=rows.filter(o=>o.status!=='error'),men=ok.filter(o=>o.brandMentioned),aov=ok.filter(o=>o.modelId==='overview');
 const mentionRate=ok.length?men.length/ok.length*100:null;
 return {n:ok.length,som:average(ok.map(voice)),mentions:men.length,mentionRate,appearance:mentionRate,citations:ok.filter(o=>o.brandCited).length,citationFrequency:ok.length?ok.filter(o=>o.brandCited).length/ok.length*100:null,sentiment:average(ok.map(o=>o.sentiment)),position:average(men.map(o=>o.position).filter(p=>Number.isFinite(p)&&p>0)),aovCount:aov.length,aovBlock:aov.length?aov.filter(o=>o.blockAppeared).length/aov.length*100:null};
}
function delta(now,prior,unit='pp',lowerIsBetter=false){if(!Number.isFinite(now)||!Number.isFinite(prior))return '<span class="trend flat">Sin periodo anterior</span>';const n=now-prior,bad=lowerIsBetter?n>0:n<0;return `<span class="trend ${bad?'down':n===0?'flat':''}">${n>0?'↑':n<0?'↓':'→'} ${fmt(Math.abs(n),unit==='pts'?2:unit==='pp'||unit==='pos.'?1:0)} ${unit}</span>`}
function snapshot(rows){const map=new Map;for(const o of rows){const k=[o.projectId,o.modelId,o.promptId].join('|');if(!map.has(k)||map.get(k).date<o.date)map.set(k,o)}return [...map.values()]}
function allEmpty(message='No hay registros para esta combinación de filtros.'){return `<div class="monitor-empty"><h3>Sin datos disponibles</h3><p>${message}</p></div>`}
function filterLabel(){return M.models.size===MON.models.length?'Todos los motores':M.models.size===1?MODEL.get([...M.models][0]).short||MODEL.get([...M.models][0]).name:M.models.size+' motores'}
function go(route,project=null){M.route=route;M.prompt='all';M.query='';M.page=1;state.page=1;state.query='';if(project)M.project=project;else if(route==='dashboard'||route==='projects')M.project='all';const hash=route==='detail'?'#proyecto/'+M.project:'#'+route;if(location.hash!==hash)history.pushState(null,'',hash);renderShell();renderRoute();window.scrollTo({top:0,behavior:'instant'})}
function renderShell(){const current=M.route==='detail'?'projects':M.route;const menus=[['dashboard','Dashboard','chart'],['projects','Proyectos','folder'],['prompts','Prompts / Consultas','search'],['competitors','Competidores','people'],['sources','Fuentes','external'],['settings','Configuración','settings']];$('#sidebar').innerHTML=`<div class="side-brand"><button type="button" class="bcp-brand-home" data-nav="dashboard" aria-label="BCP · Ir al Dashboard"><img class="bcp-wordmark" src="assets/logo-bcp.svg?v=bcp-20261020-4" width="138" height="36" alt="BCP · Banco de Crédito del Perú"></button><p>Monitor de Visibilidad en IA</p></div><div class="workspace-label">Marketing y comunicaciones</div><nav class="side-nav" aria-label="Navegación principal">${menus.map(([key,label,ic])=>`<button class="side-link ${current===key?'active':''}" data-nav="${key}" ${current===key?'aria-current="page"':''}>${navIcon(ic)}${label}</button>`).join('')}</nav><div class="side-footer"><b>BCP GEO Monitor</b>${LIVE?'Datos en vivo · GEO Tracker (n8n)<br>'+LIVE.respuestas+' respuestas registradas':'Vista privada · Datos locales<br>Versión de demostración'}</div>`;
 $('#appHeader').innerHTML=`<div><div class="app-title"><button type="button" class="header-logo" data-nav="dashboard" aria-label="BCP · Ir al Dashboard"><img src="assets/logo-bcp.svg?v=bcp-20261020-4" width="115" height="30" alt="BCP"></button><span class="app-product-name">Monitor de Visibilidad en IA</span></div><div class="breadcrumb"><button data-nav="dashboard">Dashboard</button>${M.route==='detail'?`<span>›</span><span>${esc(PROJECT.get(M.project).name)}</span>`:M.route!=='dashboard'?`<span>›</span><span>${menus.find(m=>m[0]===M.route)?.[1]||''}</span>`:'<span>›</span><span>Vista general</span>'}</div></div><div class="header-right"><span><i class="status-dot"></i>${LIVE?'Datos en vivo':LIVE_STATUS==='sin_corridas'?'Demo · aún sin corridas':LIVE_STATUS==='error'?'Demo · sin conexión con n8n':'Entorno de demostración'}</span><div class="avatar" title="BCP Marketing"><img src="assets/bcp-symbol.svg?v=bcp-20261020-4" width="22" height="22" alt="BCP"></div></div>`;renderFilters()}
function navIcon(name){const paths={folder:'<path d="M3 7V5h6l2 2h10v13H3z"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3m1-15a3 3 0 0 1 0 6m3 9v-3a5 5 0 0 0-2-4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 3-1 3-3 1-3 3 2 3-1 3 3 3h3l3 2 3-2 3-1 1-3-1-3 1-3-3-2-1-3h-3z"/>'};return paths[name]?`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]}</svg>`:icon(name)}
function renderFilters(){const rows=observations();const examples=rows.some(o=>o.isExample);$('#globalFilters').innerHTML=`<div class="filter-bar"><div class="filter-control">${icon('calendar')}<label for="globalPeriod">Periodo</label><select id="globalPeriod"><option value="30" ${M.period==='30'?'selected':''}>Últimos 30 días</option><option value="90" ${M.period==='90'?'selected':''}>Últimos 90 días</option><option value="180" ${M.period==='180'?'selected':''}>Últimos 6 meses</option><option value="source" ${M.period==='source'?'selected':''}>${LIVE?'Todos los registros disponibles':'Original · ChatGPT · 14 jul 2026'}</option></select></div><div class="filter-control engine-filter"><span class="filter-caption">Motor</span><button id="engineTrigger" class="engine-trigger" aria-expanded="false">${esc(filterLabel())} <span>⌄</span></button><div class="engine-menu" id="engineMenu" hidden><button class="text-button" id="engineAll">${M.models.size===5?'Deseleccionar todos':'Seleccionar todos'}</button>${MON.models.map(m=>`<label><input type="checkbox" data-engine="${m.id}" ${M.models.has(m.id)?'checked':''}>${engineBadge(m.id)}<small>${m.vendor}</small></label>`).join('')}</div></div><div class="filter-control"><label for="globalProject">Proyecto</label><select id="globalProject"><option value="all">Todos los proyectos</option>${MON.projects.map(p=>`<option value="${p.id}" ${M.project===p.id?'selected':''}>${esc(p.name)}${p.example?' · Ejemplo':''}</option>`).join('')}</select></div><span class="filter-asof">${LIVE?'Corte: '+dateLabel(MON.referenceDate,true):'Corte de demostración: 20 oct 2026'}</span></div><div class="demo-notice"><span class="dot"></span>${LIVE?`<span>Datos en vivo del GEO Tracker (n8n). Share of Voice calculado por n8n: pondera posición, prominencia y contexto frente a otros bancos. Los indicadores excluyen las respuestas con error.</span>`:`<span>${examples?'Datos de demostración. Los nuevos motores, proyectos y periodos usan registros simulados. ':M.period==='source'?'Registros originales: métricas de ChatGPT del 14 jul 2026. Los campos no incluidos en la fuente muestran «—». ':'No hay registros en la selección actual. '}Share of Voice presenta el valor disponible como indicador de visibilidad. Sin conexión a APIs.</span>`}</div>`}
function renderRoute(){const detail=M.route==='detail';$('#detailView').hidden=!detail;$('#generalView').hidden=detail;if(detail){renderConfig();renderKpis();$('#projectName').textContent=PROJECT.get(M.project).name;$('.project-header .brand').textContent='BCP · Detalle del proyecto';render()}else({dashboard:renderDashboard,projects:renderProjects,prompts:renderPrompts,competitors:renderCompetitorsPage,sources:renderSourcesPage,settings:renderSettings}[M.route]||renderDashboard)()}
const pageIntro=(label,sub,kicker='Monitor de visibilidad')=>`<div class="page-intro"><div><div class="orange-label">${kicker}</div><h1>${label}</h1><p>${sub}</p></div><span class="live-badge"><span class="status-dot"></span>Vista consolidada</span></div>`;
function homeKpis(rows,prior){
 const a=summary(rows),b=summary(prior);
 const defs=[['Share of Voice',fmt(a.som)+'%',a.som,b.som,'pp',SOV_TIP],['Posición promedio',fmt(a.position),a.position,b.position,'pos.',MON.metricDefinitions.position],['% de mención',fmt(a.mentionRate)+'%',a.mentionRate,b.mentionRate,'pp',MON.metricDefinitions.mentionRate],['Menciones de BCP',fmt(a.mentions,0),a.mentions,b.n?b.mentions:null,'','Número de respuestas válidas que mencionan a BCP.'],['Citaciones de BCP',fmt(a.citations,0),a.citations,b.n?b.citations:null,'','Respuestas que citan al menos una URL de BCP.'],['Sentimiento promedio',fmt(a.sentiment,2),a.sentiment,b.sentiment,'pts','Promedio de puntuaciones disponibles entre −1 y +1.'],['Frecuencia de citación',fmt(a.citationFrequency)+'%',a.citationFrequency,b.citationFrequency,'pp','Respuestas con cita de BCP sobre respuestas válidas.']];
 return `<div class="home-kpis">${defs.map(([label,val,n,p,u,tip])=>`<article class="card home-kpi"><div class="metric-title">${label}<button class="info" data-tip="${esc(tip)}" aria-label="${esc(tip)}"></button></div><div class="metric-number">${n===null?'—':val}</div><div class="metric-change">${delta(n,p,u,u==='pos.')} <span class="muted">vs. anterior</span></div></article>`).join('')}</div>`;
}
function engineBars(rows){const series=MON.models.filter(m=>M.models.has(m.id)).map(m=>({m,stat:summary(rows.filter(o=>o.modelId===m.id))}));if(!rows.length)return allEmpty();return `<div class="bar-list">${series.map(({m,stat})=>`<div class="engine-bar-row">${engineBadge(m.id)}<div class="bar-track"><div class="bar-fill" style="background:${m.color};width:${stat.som??0}%"></div></div><span class="bar-value">${stat.som===null?'—':fmt(stat.som)+'%'}</span></div>`).join('')}</div><div class="chart-caption">Share of Voice promedio · Escala de 0% a 100%</div>`}
function engineLines(rows,metric='som',chartId='homeLine'){if(!rows.length)return allEmpty();const dates=[...new Set(rows.map(o=>o.date))].sort(),W=800,H=250,L=38,R=15,T=15,B=32;const max=metric==='som'?100:metric==='sentiment'?1:metric==='position'?10:100,x=i=>dates.length===1?(W+L-R)/2:L+i*(W-L-R)/(dates.length-1),y=v=>T+(1-v/max)*(H-T-B);let h=`<div class="monitor-chart" id="${chartId}"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución por motor de ${metric==='som'?'Share of Voice':metric}">`;for(let i=0;i<=4;i++){const v=max*i/4;h+=`<path d="M${L} ${y(v)}H${W-R}" stroke="#EDF1F7" stroke-width="1"/><text x="${L-8}" y="${y(v)+3}" font-family="${BCP_FONT}" font-size="9" fill="#9AA9BF" text-anchor="end">${fmt(v,max===1?2:0)}${metric==='som'?'%':''}</text>`}
const values={};for(const m of MON.models.filter(m=>M.models.has(m.id))){const vals=dates.map(d=>{const r=rows.filter(o=>o.modelId===m.id&&o.date===d),s=summary(r);return metric==='linkPosition'?r.filter(o=>o.linkPosition!==null).length?r.reduce((n,o)=>n+(o.linkPosition||0),0)/r.filter(o=>o.linkPosition!==null).length:null:s[metric]});values[m.id]=vals;let parts=[];let current=[];vals.forEach((v,i)=>{if(v===null){if(current.length)parts.push(current);current=[]}else current.push([x(i),y(v)])});if(current.length)parts.push(current);for(const part of parts){h+=`<polyline points="${part.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${m.color}" stroke-width="2.2" stroke-linejoin="round"/>`;h+=part.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${m.color}" stroke="white" stroke-width="1.2"/>`).join('')}}dates.forEach((d,i)=>{if(dates.length<8||i%Math.ceil(dates.length/7)===0||i===dates.length-1)h+=`<text x="${x(i)}" y="${H-8}" text-anchor="middle" font-size="9" fill="#9AA9BF" font-family="${BCP_FONT}">${dateLabel(d)}</text>`;h+=`<rect x="${x(i)-18}" y="0" width="36" height="${H-B}" fill="transparent" data-trend-date="${d}" data-trend-chart="${chartId}" tabindex="0" role="button" aria-label="${dateLabel(d)}: ${MON.models.filter(m=>M.models.has(m.id)).map(m=>m.name+' '+fmt(values[m.id]?.[i])).join(', ')}"><title>${dateLabel(d,true)}${MON.models.filter(m=>M.models.has(m.id)).map(m=>'\n'+m.name+': '+fmt(values[m.id]?.[i])+(metric==='som'?'%':'')).join('')}</title></rect>`});h+=`</svg></div><div class="chart-legend">${MON.models.filter(m=>M.models.has(m.id)).map(m=>engineBadge(m.id,true)).join('')}</div>`;return h}
function canonicalBrand(value){
 const brand=String(value||'').trim(),key=brand.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
 if(key==='bcp'||key==='banco de credito del peru')return 'BCP';
 if(key==='bbva'||key==='bbva peru')return 'BBVA';
 if(key==='scotiabank'||key==='scotiabank peru')return 'Scotiabank';
 if(key==='interbank')return 'Interbank';
 return brand;
}
function competitorStats(rows){
 const ok=rows.filter(o=>o.status!=='error');if(!ok.length)return [];
 const brands=new Set(['BCP']),data=ok.map(o=>{
  const scores=new Map,details=new Map,ranking=(o.ranking||[]).map(canonicalBrand);
  const hasScores=o.sovByBrand!==null&&typeof o.sovByBrand==='object'&&!Array.isArray(o.sovByBrand);
  for(const [name,value] of Object.entries(hasScores?o.sovByBrand:{})){const brand=canonicalBrand(name);if(brand){brands.add(brand);if(Number.isFinite(value))scores.set(brand,value)}}
  for(const d of o.brandDetail||[]){const brand=canonicalBrand(d.marca);if(brand){brands.add(brand);details.set(brand,d)}}
  ranking.forEach(brand=>{if(brand)brands.add(brand)});
  return {o,scores,details,ranking,hasScores};
 });
 const hasScores=data.some(d=>d.hasScores);
 return [...brands].map(brand=>{
  let total=0,mentions=0;const positions=[];
  for(const d of data){
   const detail=d.details.get(brand),rank=d.ranking.indexOf(brand);
   const mentioned=brand==='BCP'?!!d.o.brandMentioned:detail?detail.menciones>0:rank>=0||((d.scores.get(brand)||0)>0);
   if(mentioned){mentions++;const p=brand==='BCP'?d.o.position:detail?.posicion??(rank>=0?rank+1:null);if(Number.isFinite(p)&&p>0)positions.push(p)}
   total+=d.scores.get(brand)||0;
  }
  return {brand,sov:hasScores?total/ok.length:brand==='BCP'?summary(ok).som:null,mentions,rate:100*mentions/ok.length,position:average(positions)};
 }).sort((a,b)=>(b.sov??-1)-(a.sov??-1)||b.rate-a.rate||a.brand.localeCompare(b.brand,'es'));
}
function rankingMarkup(rows,limit=5){
 let bs=competitorStats(rows);if(!bs.length)return allEmpty();
 const rank=new Map(bs.map((b,i)=>[b.brand,i+1]));
 if(bs.length>limit){const top=bs.slice(0,limit);if(!top.some(b=>b.brand==='BCP'))top[top.length-1]=bs.find(b=>b.brand==='BCP');bs=top}
 return `<div class="table-scroll"><table class="competitor-table"><thead><tr><th>#</th><th>Banco</th><th title="Promedio del Share of Voice calculado por n8n">SoV</th><th>% de mención</th><th>Posición promedio</th></tr></thead><tbody>${bs.map(b=>`<tr class="${b.brand==='BCP'?'leader':''}"><td>${rank.get(b.brand)}</td><th scope="row">${esc(b.brand)}${b.brand==='BCP'?'<span class="bcp-brand-tag">Tu marca</span>':''}</th><td><b>${b.sov===null?'—':fmt(b.sov)+'%'}</b></td><td>${fmt(b.rate)}%</td><td>${b.position===null?'—':'#'+fmt(b.position)}</td></tr>`).join('')}</tbody></table></div><p class="chart-caption">SoV promedio sobre ${summary(rows).n} respuestas válidas; un banco ausente aporta 0. Posición promedio solo donde se menciona al banco. Menor posición es mejor.${bs.some(b=>b.sov===null)?' SoV por banco no disponible en la fuente local: «—».':''}</p>`;
}
function domainStats(rows){const map=new Map;for(const o of rows)for(const s of o.sources){let d=map.get(s.domain)||{domain:s.domain,url:s.url,count:0,models:new Set,projects:new Set};d.count++;d.models.add(o.modelId);d.projects.add(o.projectId);map.set(s.domain,d)}return [...map.values()].sort((a,b)=>b.count-a.count)}
function domainsMarkup(rows){const ds=domainStats(rows).slice(0,5);return ds.length?ds.map(d=>`<div class="source-row"><div class="domain-icon">${esc(d.domain.slice(0,2).toUpperCase())}</div><div><a class="domain-name" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">${esc(d.domain)}</a><small>${d.models.size} motores · ${d.projects.size} proyectos</small></div><strong>${fmt(d.count,0)}</strong></div>`).join(''):allEmpty('No se incluyeron URLs citadas para esta selección.')}
function projectsTable(rows,prior,full=false){const ps=MON.projects.filter(p=>M.project==='all'||M.project===p.id);return `<div class="card"><div class="table-header"><div><h2>${full?'Todos los proyectos':'Resumen de proyectos'}</h2><p>Share of Voice y tendencia en el periodo seleccionado</p></div><span class="small muted">${ps.length} proyectos</span></div><div class="table-scroll"><table class="projects-table"><thead><tr><th>Proyecto</th><th>Motores</th><th>Prompts</th><th>Share of Voice</th><th>Tendencia</th><th>Detalle</th></tr></thead><tbody>${ps.map(p=>{const rs=rows.filter(o=>o.projectId===p.id),a=summary(rs),b=summary(prior.filter(o=>o.projectId===p.id));return `<tr><td><div class="project-name-cell"><div class="project-square">${p.id==='marca'?'BC':p.id==='digital'?'DX':'ME'}</div><div><b>${esc(p.name)}</b>${p.example?'<span class="demo-tag">Ejemplo</span>':''}<small>${esc(p.description)}</small></div></div></td><td><div class="project-models">${engineIcons()}</div></td><td>${p.promptIds.length}</td><td><b>${a.som===null?'—':fmt(a.som)+'%'}</b></td><td>${delta(a.som,b.som)}</td><td><button class="text-button" data-openproject="${p.id}">Ver detalle →</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function renderDashboard(){const r=observations(),p=observations({previous:true});$('#generalView').innerHTML=pageIntro('Dashboard General','La presencia de BCP en el ecosistema de inteligencia artificial.')+homeKpis(r,p)+`<div class="dashboard-grid"><section class="card dashboard-card"><div class="dash-card-header"><div><h2>Evolución del Share of Voice</h2><p class="sub">Visibilidad de BCP por motor en el tiempo</p></div><span class="small muted">${M.period==='source'?'Registro original':'Periodo seleccionado'}</span></div>${engineLines(r)}</section><section class="card dashboard-card"><div class="dash-card-header"><div><h2>Comparativo por motor</h2><p class="sub">Share of Voice de BCP</p></div></div>${engineBars(r)}</section></div><div class="dashboard-grid"><section class="card dashboard-card"><div class="dash-card-header"><div><h2>BCP frente a competidores</h2><p class="sub">Ranking por Share of Voice</p></div><button class="text-button" data-nav="competitors">Ver todos →</button></div>${rankingMarkup(r)}</section><section class="card dashboard-card"><div class="dash-card-header"><div><h2>Top fuentes citadas</h2><p class="sub">Dominios citados en el periodo</p></div><button class="text-button" data-nav="sources">Ver fuentes →</button></div>${domainsMarkup(r)}</section></div>${overviewSummary(r)}${projectsTable(r,p)}<p class="coverage-note">${r.length} observaciones · ${snapshot(r).length} combinaciones de proyecto, prompt y motor. Los registros con error se excluyen del promedio. Los periodos anteriores tienen la misma duración.</p>`}
function overviewSummary(rows){const r=rows.filter(o=>o.modelId==='overview'),s=summary(r);if(!M.models.has('overview'))return '';return `<div class="overview-panel" style="margin:0 0 20px"><span>${engineBadge('overview',true)}</span><span>Bloque generativo: <b>${s.aovBlock===null?'—':fmt(s.aovBlock)+'%'}</b></span><span>BCP mencionado: <b>${r.filter(o=>o.brandMentioned).length}</b></span><span>BCP citado: <b>${r.filter(o=>o.brandCited).length}</b></span><span>URLs citadas: <b>${r.reduce((n,o)=>n+o.sources.length,0)}</b></span></div>`}
function renderProjects(){const r=observations();$('#generalView').innerHTML=pageIntro('Proyectos','Explora cada proyecto, sus consultas y los motores que lo analizan.')+projectsTable(r,observations({previous:true}),true)}
renderConfig=function(){const p=PROJECT.get(M.project),r=observations(),latest=r.length?r.map(o=>o.date).sort().at(-1):null;$('#config').innerHTML=`<div class="config-item"><div class="eyebrow">Motores de IA</div><div class="engine-small-set">${engineIcons()||'<span class="muted">Sin selección</span>'}</div></div><div class="config-item"><div class="eyebrow">Prompts activos</div><div class="config-value">${p.promptIds.length}</div></div><div class="config-item"><div class="eyebrow">País</div><div class="config-value"><span class="tag">PE</span> Perú</div></div><div class="config-item"><div class="eyebrow">Último registro</div><div class="config-value">${icon('clock')}${latest?dateLabel(latest,true):'Sin datos'}</div></div>`};
renderKpis=function(){
 if(M.route!=='detail')return;
 const rows=observations(),a=summary(rows),b=summary(observations({previous:true})),valid=rows.filter(o=>o.status!=='error');
 const metrics=[['Share of Voice',a.som===null?'—':fmt(a.som)+'%','',SOV_TIP,delta(a.som,b.som)],['Posición promedio',fmt(a.position),'',MON.metricDefinitions.position,delta(a.position,b.position,'pos.',true)],['% de mención',a.mentionRate===null?'—':fmt(a.mentionRate)+'%','',MON.metricDefinitions.mentionRate,delta(a.mentionRate,b.mentionRate)],['Menciones de marca',fmt(a.mentions,0),'respuestas','Respuestas válidas que mencionan a BCP.'],['Frecuencia de citación',a.citationFrequency===null?'—':fmt(a.citationFrequency)+'%','',MON.metricDefinitions.citations],['Sentimiento promedio',fmt(a.sentiment,2),'de −1 a +1',MON.metricDefinitions.sentiment],['Primera Mención',fmt(valid.filter(o=>o.position===1).length,0),`de ${valid.length}`,'Respuestas donde BCP es el primer competidor mencionado.'],['Aparición Temprana',!LIVE&&M.period==='source'?23:'—',!LIVE&&M.period==='source'?'de 37':'sin dato','La fuente original registra 23 de 37. Los datos simulados no incluyen la posición dentro del texto.'],['Citaciones',fmt(a.citations,0),'respuestas','Respuestas que citan una URL de BCP.'],['Bloque AI Overview',a.aovBlock===null?'—':fmt(a.aovBlock)+'%','','Frecuencia de aparición del bloque generativo de Google en los registros de AI Overview.']];
 const count=innerWidth<768?1:4,max=metrics.length-count;state.kpi=Math.max(0,Math.min(state.kpi,max));
 $('#kpis').innerHTML=metrics.slice(state.kpi,state.kpi+count).map(k=>`<article class="card kpi"><div class="kpi-label">${k[0]}<button class="info" data-tip="${esc(k[3])}" aria-label="${esc(k[3])}"></button></div><div class="kpi-value">${k[1]}<small>${k[2]}</small></div>${k[4]?`<div class="kpi-comparison">${k[4]} <span class="muted">vs. anterior</span></div>`:''}</article>`).join('');
 $('#dots').innerHTML=Array.from({length:max+1},(_,i)=>`<button class="dot ${i===state.kpi?'active':''}" data-kpi="${i}" aria-label="Grupo ${i+1} de indicadores"></button>`).join('');$('#kpiPrev').disabled=state.kpi===0;$('#kpiNext').disabled=state.kpi===max;
};
function promptRows(){
 const records=snapshot(observations()).filter(o=>{const p=promptMap.get(o.promptId);const q=state.query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();return (p.text+' '+MODEL.get(o.modelId).name+' '+PROJECT.get(o.projectId).name).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q)});
 if(state.sort)records.sort((a,b)=>{const av=state.sort==='sov'?voice(a):a[state.sort],bv=state.sort==='sov'?voice(b):b[state.sort];return av==null?bv==null?0:1:bv==null?-1:(av-bv)*state.dir});return records;
}
renderPrompts=function(){const target=M.route==='detail'?'#view':'#generalView';const list=promptRows(),pages=Math.max(1,Math.ceil(list.length/10));state.page=Math.min(state.page,pages);const start=(state.page-1)*10;const intro=M.route==='detail'?'':pageIntro('Prompts / Consultas','Consulta las respuestas y métricas por proyecto y motor.');$(target).innerHTML=intro+`<div class="view-header"><h2>${M.route==='detail'?'Performance por Prompt':'Consultas monitoreadas'}</h2><label class="search">${icon('search')}<input id="promptSearch" type="search" placeholder="Buscar prompt, motor o proyecto..." aria-label="Buscar prompt" value="${esc(state.query)}"></label></div>${overviewSummary(list)}<div class="card"><div class="table-scroll"><table class="monitor-prompt-table"><thead><tr><th>Prompt / Keyword</th><th>Motor</th>${[['position','Posición'],['linkPosition','Enlace'],['sov','Share of Voice']].map(([key,label])=>`<th><button class="sort" data-sort="${key}">${label} ⇅</button></th>`).join('')}<th>Mención</th><th>Cita BCP</th><th>Sentimiento</th><th>Bloque AIO</th><th>Ranking de marcas</th><th>Detalle</th></tr></thead><tbody>${list.slice(start,start+10).map(o=>{const p=promptMap.get(o.promptId);return `<tr><td>${esc(p.text)}<div class="small muted" style="font-size:8px;margin-top:4px">${M.route==='detail'?'':esc(PROJECT.get(o.projectId).name)+' · '}${dateLabel(o.date)}${o.isExample?' · Ejemplo':''}</div></td><td>${engineBadge(o.modelId,true)}</td><td>${position({status:o.status,position:o.position})}</td><td>${o.linkPosition?`<span class="tag">#${o.linkPosition}</span>`:'<span class="muted">Sin enlace</span>'}</td><td><b>${voice(o)===null?'—':fmt(voice(o))+'%'}</b></td><td>${o.status==='error'?'—':o.brandMentioned?'<span class="check">✓ Sí</span>':'<span class="muted">No</span>'}</td><td>${o.status==='error'?'—':o.brandCited?'<span class="check">✓ Sí</span>':'<span class="muted">No</span>'}</td><td>${sentimentBadge(o)}</td><td>${o.modelId==='overview'?o.blockAppeared?'<span class="overview-yes">✓ Aparece</span>':'<span class="overview-no">No aparece</span>':'<span class="muted">—</span>'}</td><td><div class="rank-lines">${(state.expanded.has(o.id)?o.ranking:o.ranking.slice(0,3)).map((b,i)=>`<div><span class="rank-num">#${i+1}</span>${b==='BCP'?`<b>${b}</b>`:esc(b)}</div>`).join('')||'—'}</div>${o.ranking.length>3?`<button class="text-button" data-rank="${o.id}">${state.expanded.has(o.id)?'Ver menos ⌃':'Ver '+(o.ranking.length-3)+' más ⌄'}</button>`:''}</td><td><button class="text-button" data-detail="${o.id}">Ver detalle</button></td></tr>`}).join('')||'<tr><td colspan="11">'+allEmpty()+'</td></tr>'}</tbody></table></div><div class="pagination"><span>Mostrando ${list.length?start+1:0} a ${Math.min(start+10,list.length)} de ${list.length} registros</span><div class="pages"><button class="page-btn" data-page="-1" ${state.page===1?'disabled':''} aria-label="Página anterior">‹</button><span>${state.page} / ${pages}</span><button class="page-btn" data-page="1" ${state.page===pages?'disabled':''} aria-label="Página siguiente">›</button></div></div></div><p class="coverage-note">Una fila por prompt, proyecto y motor. Se muestra el registro más reciente dentro del periodo filtrado.</p>`};
function sentimentBadge(o){return o.sentiment===null?'<span class="muted">—</span>':`<span class="sentiment ${o.sentimentLabel}">${esc(o.sentimentLabel)} ${fmt(o.sentiment,2)}</span>`}
showResponse=function(id){const o=observationMap.get(id);if(!o)return;const p=promptMap.get(o.promptId),m=MODEL.get(o.modelId);const response=o.status==='error'?'No se pudo completar el análisis. No hay una respuesta guardada.':!o.isExample?(o.response||(!LIVE&&p.response?.text)||'No hay respuesta guardada.'):o.modelId==='overview'&&!o.blockAppeared?'No apareció un bloque generativo de Google para esta keyword en el registro de demostración.':`Respuesta de ejemplo de ${m.name} para «${p.text}».\n\n${o.brandMentioned?'BCP es mencionado en la respuesta'+(o.position?' en la posición #'+o.position:'')+'.':'BCP no fue mencionado en este registro.'} ${o.brandCited?'La respuesta incluye una cita a una URL de BCP.':'No se registró una cita a una URL de BCP.'}\n\nLas marcas incluidas en este ejemplo son: ${o.ranking.join(', ')||'sin marcas registradas'}. Sustituir este texto por la respuesta literal del motor al conectar las fuentes.`;modalShell(`${m.icon} Respuesta del motor · ${esc(m.name)}`,`<p class="prompt-quote">“${esc(p.text)}”</p><p class="small muted">${esc(PROJECT.get(o.projectId).name)} · ${dateLabel(o.date,true)} · ${m.vendor}</p><div class="sample-banner">${o.isExample?'Registro simulado de demostración.':LIVE?'Respuesta real capturada por el GEO Tracker (n8n). Análisis hecho por IA.':'Métricas originales del requerimiento. Respuesta literal y URLs no disponibles; el texto mostrado es ilustrativo.'}</div><div class="metric-details-list">${[['Share of Voice',voice(o)===null?'—':fmt(voice(o))+'%'],['Posición',o.position?'#'+o.position:'—'],['Primera fuente de BCP',o.linkPosition?'#'+o.linkPosition:'—'],['BCP mencionado',o.status==='error'?'—':o.brandMentioned?'Sí':'No'],['BCP citado',o.status==='error'?'—':o.brandCited?'Sí':'No'],['Sentimiento',fmt(o.sentiment,2)],['Fuentes citadas',o.sources.length||'—']].map(([k,v])=>`<div class="metric-detail"><span>${k}</span><b>${v}</b></div>`).join('')}</div>${o.modelId==='overview'?`<div class="overview-panel">Bloque generativo: <b>${o.blockAppeared?'Sí aparece':'No aparece'}</b><span>BCP mencionado: <b>${o.brandMentioned?'Sí':'No'}</b></span><span>BCP citado: <b>${o.brandCited?'Sí':'No'}</b></span></div>`:''}<div class="response-text">${esc(response)}</div><div class="model-response-sources"><h3 class="section-label">Fuentes y URLs citadas</h3>${o.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">↗ ${esc(s.url)}</a>`).join('')||'<p class="small muted">Sin URLs registradas en esta fuente.</p>'}</div><h3 class="section-label" style="margin-top:25px">Captura de pantalla</h3><div class="screenshot">Sin captura guardada para este análisis.</div>`)};
selectedLabel=function(){const ids=PROJECT.get(M.project)?.promptIds||DATA.prompts.map(p=>p.id);const n=ids.filter(id=>state.selected.has(id)).length;return n===ids.length?'Todos los prompts ('+n+')':n+' prompts seleccionados'};
function selectedObservations(){return observations().filter(o=>state.selected.has(o.promptId))}
renderCompetitive=function(){const r=selectedObservations(),p=PROJECT.get(M.project);$('#view').innerHTML=`<div class="view-header"><div><h2>Evolución de la Competencia</h2><p>Compara BCP por motor y frente a las marcas mencionadas</p></div></div><div class="toolbar"><div class="multi"><button class="button" id="multiToggle" aria-expanded="false">${icon('search')} ${selectedLabel()} ⌄</button><div id="multiPanel" class="multi-panel" hidden><div style="display:flex;justify-content:space-between"><span class="eyebrow">Seleccionar prompts</span><button class="text-button" id="selectAll">${state.selected.size?'Deseleccionar todas':'Seleccionar todas'}</button></div><div class="multi-list">${p.promptIds.map(id=>{const pp=promptMap.get(id);return `<label class="multi-label"><input type="checkbox" data-select="${id}" ${state.selected.has(id)?'checked':''}><span>${esc(pp.text)}</span><small>SoV: ${fmt(summary(r.filter(o=>o.promptId===id)).som)}%</small></label>`}).join('')}</div></div></div><div class="segment">${[['1m','1 mes','30'],['3m','3 meses','90'],['6m','6 meses','180']].map(([key,label,days])=>`<button data-range="${key}" class="${M.period===days?'active':''}">${label}</button>`).join('')}</div></div><div class="competitive"><section class="card chart-card" id="chartCard"><div class="card-head"><h3>Evolución Comparativa</h3><button class="fullscreen-btn" id="fullscreen" aria-label="Ampliar gráfico">${icon('expand')}</button></div><div class="chart-tools">${metricSegment(state.chartMetric,'chartmetric')}<span class="small muted" id="pointCount">${new Set(r.map(o=>o.date)).size} puntos de datos</span></div><div id="chart"></div><p class="chart-caption">Líneas por motor · Share of Voice y posiciones promedio</p></section><aside class="card ranking"><div class="card-head"><h3>RANKING ACTUAL</h3><small>Periodo filtrado</small></div><div class="ranking-list" id="detailRanking">${rankingMarkup(r,10)}</div></aside></div><section id="brandHistory" class="card dashboard-card" style="margin-top:20px"></section><section class="history"><div class="view-header"><div><h2>Historial de Respuestas IA</h2><p>Clic en celda para ver respuesta completa</p></div>${metricSegment(state.historyMetric,'historymetric',true)}</div><div class="sample-banner">Datos por prompt y motor · Los registros simulados se identifican en el detalle de la respuesta.</div><div class="card table-scroll" id="historyTable"></div></section>`;renderChart();renderHistory()};
renderChart=function(){if(!$('#chart'))return;const r=selectedObservations();const metric=state.chartMetric==='sov'?'som':state.chartMetric;$('#chart').innerHTML=engineLines(r,metric,'detailLine');if($('#pointCount'))$('#pointCount').textContent=new Set(r.map(o=>o.date)).size+' puntos de datos';if($('#detailRanking'))$('#detailRanking').innerHTML=rankingMarkup(r,10);renderBrandHistory()};
renderHistory=function(){if(!$('#historyTable'))return;const r=selectedObservations(),dates=[...new Set(r.map(o=>o.date))].sort().reverse(),sn=snapshot(r),idx=new Map(r.map(o=>[[o.modelId,o.promptId,o.date].join('|'),o]));$('#historyTable').innerHTML=dates.length?`<table class="history-table"><thead><tr><th>Prompt</th><th>Motor</th>${dates.map(d=>`<th>${dateLabel(d,true).toUpperCase()}</th>`).join('')}</tr></thead><tbody>${sn.map(o=>`<tr><td>${esc(promptMap.get(o.promptId).text)}</td><td>${engineBadge(o.modelId,true)}</td>${dates.map(d=>{const h=idx.get([o.modelId,o.promptId,d].join('|'));if(!h)return '<td><span class="muted small">Sin análisis</span></td>';const val=state.historyMetric==='sov'?voice(h):h[state.historyMetric];return `<td><button class="cell-button" data-detail="${h.id}">${h.status==='error'?'<span class="red">⊗ Error</span>':`<span class="cell-main">${val===null?'—':(state.historyMetric==='sov'?val+'%':'#'+val)}</span>${h.brandMentioned?'<span class="check">✓</span>':'<span class="small muted"> Marca no mencionada</span>'}`}<span class="history-engine" style="display:block;color:${MODEL.get(o.modelId).color};font-size:8px;margin-top:5px">${MODEL.get(o.modelId).icon} ${MODEL.get(o.modelId).short||MODEL.get(o.modelId).name}</span></button></td>`}).join('')}</tr>`).join('')}</tbody></table>`:allEmpty()};
function sourceTable(rows){const list=snapshot(rows);return `<div class="card table-scroll"><table class="monitor-source-table"><thead><tr><th>Prompt</th><th>Motor</th><th>Fecha</th><th>Fuentes / URLs citadas</th><th>Mención BCP</th><th>Cita BCP</th><th>Primera fuente BCP</th><th>Bloque AIO</th><th>Detalle</th></tr></thead><tbody>${list.map(o=>`<tr><td>${esc(promptMap.get(o.promptId).text)}</td><td>${engineBadge(o.modelId,true)}</td><td>${dateLabel(o.date)}</td><td>${o.sources.map(s=>`<a class="reference-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${icon('external')} ${esc(s.domain)}</a>`).join('<br>')||'<span class="muted">Sin fuentes</span>'}</td><td>${o.status==='error'?'—':o.brandMentioned?'<span class="tag success">Sí</span>':'No'}</td><td>${o.status==='error'?'—':o.brandCited?'<span class="tag success">Sí</span>':'No'}</td><td>${o.status!=='error'&&o.brandCited&&Number.isFinite(o.linkPosition)?'#'+o.linkPosition:'—'}</td><td>${o.modelId==='overview'?o.blockAppeared?'Sí':'No':'—'}</td><td><button class="text-button" data-detail="${o.id}">Ver detalle</button></td></tr>`).join('')||'<tr><td colspan="9">'+allEmpty()+'</td></tr>'}</tbody></table></div>`}
function sourceHistory(rows){const sn=snapshot(rows),dates=[...new Set(rows.map(o=>o.date))].sort().reverse(),idx=new Map(rows.map(o=>[[o.modelId,o.promptId,o.date].join('|'),o]));if(!sn.length)return allEmpty();return `<div class="card table-scroll"><table class="references"><thead><tr><th rowspan="2">Prompt / Motor</th><th rowspan="2">URL</th>${dates.map(d=>`<th colspan="2">${dateLabel(d,true).toUpperCase()}</th>`).join('')}</tr><tr>${dates.map(()=>'<th>Mención</th><th>1ª fuente BCP</th>').join('')}</tr></thead><tbody>${sn.map(o=>`<tr><td>${esc(promptMap.get(o.promptId).text)}<div style="margin-top:5px">${engineBadge(o.modelId,true)}</div></td><td>${o.sources.map(s=>`<a class="reference-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(s.domain)}</a>`).join('<br>')||'<span class="muted">Sin fuentes</span>'}</td>${dates.map((d,i)=>{const h=idx.get([o.modelId,o.promptId,d].join('|')),prev=idx.get([o.modelId,o.promptId,dates[i+1]].join('|'));const change=h&&prev&&h.mentions!==null&&prev.mentions!==null?h.mentions-prev.mentions:null;return `<td>${!h||h.mentions===null?'—':`<span class="tag success">${h.mentions}</span>${change?`<span class="delta" style="color:${change>0?'#1d8b3d':'#d02c2a'}">${change>0?'↑':'↓'}${Math.abs(change)}</span>`:''}`}</td><td>${h&&h.status!=='error'&&h.brandCited&&Number.isFinite(h.linkPosition)?'#'+h.linkPosition:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
renderReferences=function(){const r=sourceRows();$('#view').innerHTML=`<div class="view-header"><div><h2>Referencias y Fuentes</h2><p>Seguimiento histórico de menciones de marca y enlaces de referencia por prompt y motor</p></div><button class="button green" id="exportReferences">${icon('download')}Exportar a Excel</button></div>${sourceFilter()}${overviewSummary(r)}${sourceTable(r)}<h2 class="monitor-subtable" style="margin-bottom:15px">Historial de menciones y enlaces</h2>${sourceHistory(r)}<p class="coverage-note">${LIVE?'URLs y posiciones de fuentes recibidas de n8n. Los valores sin dato se muestran con «—».':'Datos locales de demostración; los valores sin fuente muestran «—». Los registros simulados se identifican en su detalle.'}</p>`};
renderRecs=function(){if(!M.models.has('chatgpt')||M.project!=='marca'){$('#view').innerHTML='<div class="view-header"><h2>Acciones Sugeridas</h2></div><div class="card">'+allEmpty('No hay recomendaciones documentadas para este proyecto y los motores seleccionados. El backlog original pertenece a ChatGPT / BCP Marca Chatgpt.')+'</div>';return}originals.renderRecs();$('#view').insertAdjacentHTML('afterbegin',`<div class="detail-engine-note">${engineBadge('chatgpt',true)} Backlog original de ChatGPT · 35 recomendaciones documentadas. No se han generado recomendaciones para los motores nuevos. Estados editables durante esta sesión.</div>`)};
renderBI=function(){const ps=PROJECT.get(M.project).promptIds;const months=Array.from({length:11},(_,i)=>{const d=new Date(2025,10+i,1);return {value:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),label:d.toLocaleDateString('es-PE',{month:'long',year:'numeric'})}});$('#view').innerHTML=`<div class="view-header"><h2>Brand Intelligence</h2></div><div class="card bi-bar"><select id="biPrompt" aria-label="Prompt de Brand Intelligence"><option value="all">Todos los prompts</option>${ps.map(id=>`<option value="${id}" ${state.biPrompt===id?'selected':''}>${esc(promptMap.get(id).text)}</option>`).join('')}</select><div class="bi-compare"><b>Octubre 2026</b><span>vs</span><select id="biMonth" aria-label="Mes de comparación">${months.map(m=>`<option value="${m.value}" ${state.biMonth===m.value?'selected':''}>${esc(m.label)}</option>`).join('')}</select></div></div><div id="biContent" class="bi-content"></div>`;renderBIContent()};
renderBIContent=function(){if(!$('#biContent'))return;const current=observations().filter(o=>o.date.startsWith('2026-10')&&(state.biPrompt==='all'||o.promptId===state.biPrompt));const past=MON.observations.filter(o=>M.models.has(o.modelId)&&o.projectId===M.project&&o.date.startsWith(state.biMonth)&&(state.biPrompt==='all'||o.promptId===state.biPrompt)&&(M.period!=='source'||!o.isExample));if(!current.length||!past.length){$('#biContent').innerHTML=`<div class="card empty">${icon('chart')}<h3>No hay datos KPI para el período seleccionado</h3><p>Revisa el periodo global, los motores o el mes de comparación.</p></div>`;return}if(state.biMonth==='2026-08'&&DATA.brandIntelligence.states['2026-08']==='error'){$('#biContent').innerHTML='<div class="sample-banner">Estado de error de ejemplo; no se realizó una llamada a una API.</div><div class="alert"><span>⚠ No se pudieron cargar los KPIs. Intente nuevamente.</span><button class="text-button" id="retryBI">Reintentar</button></div>';return}const a=summary(current),b=summary(past);$('#biContent').innerHTML=`<div class="sample-banner">Comparación ilustrativa por motor. Octubre respeta el periodo global; el comparador toma el mes seleccionado completo.</div><div class="bi-cards">${[['% de mención',a.mentionRate,b.mentionRate],['% mención en primer lugar',100*current.filter(o=>o.position===1).length/(a.n||1),100*past.filter(o=>o.position===1).length/(b.n||1)]].map(([title,n,p])=>`<div class="card bi-card"><h3>${title}</h3><div class="bi-value">${fmt(n)}%</div>${delta(n,p)}<p class="small muted" style="margin-top:9px">Mes comparado: ${fmt(p)}%</p></div>`).join('')}</div><div class="card dashboard-card" style="margin-top:20px"><div class="dash-card-header"><h2>Share of Voice por motor</h2></div>${engineBars(current)}</div>`};
function renderCompetitorsPage(){const r=observations();$('#generalView').innerHTML=pageIntro('Competidores','Share of Voice, % de mención y posición promedio por banco.')+`<div class="dashboard-grid"><section class="card dashboard-card"><div class="dash-card-header"><h2>Ranking frente a BCP</h2></div>${rankingMarkup(r,Infinity)}</section><section class="card dashboard-card"><div class="dash-card-header"><h2>Visibilidad de BCP por motor</h2></div>${engineBars(r)}</section></div><div class="card dashboard-card"><div class="dash-card-header"><h2>Evolución del Share of Voice de BCP</h2></div>${engineLines(r,'som','competitorLine')}</div>`}
function renderSourcesPage(){const r=sourceRows(),ds=domainStats(r);$('#generalView').innerHTML=pageIntro('Fuentes','Dominios y URLs que citan los motores de inteligencia artificial.')+sourceFilter()+`<div class="source-summary-grid"><div class="card mini-stat"><span>Dominios citados</span><b>${ds.length}</b><span>En los filtros actuales</span></div><div class="card mini-stat"><span>Referencias registradas</span><b>${ds.reduce((n,d)=>n+d.count,0)}</b><span>En todos los motores elegidos</span></div><div class="card mini-stat"><span>Respuestas con cita de BCP</span><b>${summary(r).citations}</b><span>${fmt(summary(r).citationFrequency)}% de las respuestas válidas</span></div></div><div class="view-header"><h2>Fuentes por consulta y motor</h2><button class="button green" id="exportReferences">${icon('download')}Exportar a Excel</button></div>${overviewSummary(r)}${sourceTable(r)}`}
function renderSettings(){$('#generalView').innerHTML=pageIntro('Configuración','Identidad, motores y definiciones de las métricas del monitor.')+`<div class="settings-grid"><section class="card settings-card"><h2>Información del monitor</h2><div class="settings-line"><span>Nombre</span><b>BCP · Monitor de Visibilidad en IA</b></div><div class="settings-line"><span>Organización</span><b>BCP · Marketing y Comunicaciones</b></div><div class="settings-line"><span>País</span><b>Perú</b></div><div class="settings-line"><span>Modo</span><b>${LIVE?'Resultados de n8n · Vista de solo lectura':'Demostración · Vista de solo lectura'}</b></div><div class="settings-line"><span>Acceso</span><b>Gestionado por Sites</b></div><div class="settings-line"><span>Conexión con motores</span><b>${LIVE?'Endpoint de lectura n8n':'Sin conexión disponible · Dataset local'}</b></div><div class="settings-line"><span>Paleta</span><b><span style="color:#002A8D">● #002A8D</span> · <span style="color:#FF7800">● #FF7800</span></b></div><p class="coverage-note">El acceso privado del monitor se administra desde la configuración del sitio.</p></section><section class="card settings-card"><h2>Motores disponibles</h2>${MON.models.map(m=>`<div class="settings-line">${engineBadge(m.id)}<b>${m.vendor}<br><small class="muted">${LIVE?(MON.observations.some(o=>o.modelId===m.id&&o.status!=='error')?'Respuestas recibidas':MON.observations.some(o=>o.modelId===m.id)?'Corrida con error':'Sin corridas'):(m.id==='chatgpt'?'Fuente original + ejemplos':'Datos de ejemplo')}</small></b></div>`).join('')}</section><section class="card settings-card" style="grid-column:1/-1"><h2>Diccionario de métricas</h2>${Object.entries(MON.metricDefinitions).map(([key,description])=>`<p class="metric-definition"><b>${({som:'Share of Voice',mentions:'Menciones',citations:'Frecuencia de citación',sentiment:'Sentimiento',comparison:'Comparación de periodos',mentionRate:'% de mención',position:'Posición promedio'})[key]}</b>${esc(description)}</p>`).join('')}<p class="metric-definition"><b>Disponibilidad y datos de ejemplo</b>${LIVE?'Los proyectos y resultados provienen del endpoint de n8n consultado al abrir el monitor. Las corridas con error se muestran y se excluyen de los promedios. Las recomendaciones y la serie histórica original se conservan como referencia local.':'Los 37 prompts y sus métricas del 14 jul pertenecen al proyecto original ChatGPT. Los datos de demostración están identificados y los valores sin dato se muestran con «—».'}</p></section></div>`}
exportPrompts=function(){const rows=snapshot(observations());const cols=['Proyecto','Motor','Prompt','Fecha','Share of Voice (%)','Mención BCP','Citación BCP','Posición','Posición enlace','Sentimiento (-1 a +1)','Bloque AI Overview','Fuentes citadas','Tipo de dato'];const data=rows.map(o=>[PROJECT.get(o.projectId).name,MODEL.get(o.modelId).name,promptMap.get(o.promptId).text,o.date,voice(o)??'',o.brandMentioned?'Sí':'No',o.brandCited?'Sí':'No',o.position??'',o.linkPosition??'',o.sentiment??'',o.blockAppeared===null?'':o.blockAppeared?'Sí':'No',o.sources.map(s=>s.url).join(' | '),o.isExample?'Ejemplo':LIVE?'GEO Tracker (n8n)':'Métricas originales']);const safe=v=>'"'+(/^[=+@\-]/.test(String(v))?"'":'')+String(v).replaceAll('"','""')+'"';download('BCP_GEO_Monitor_consultas.csv',new Blob(['\ufeff'+[cols,...data].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));toast(`CSV exportado · ${rows.length} registros · Filtros aplicados`)};
exportReferences=function(){const r=sourceRows();const rows=[['BCP GEO Monitor · Fuentes y menciones · '+(LIVE?'Datos de n8n':'Datos locales de demostración')],['Proyecto','Motor','Prompt','Fecha','Menciones (conteo)','BCP mencionado','BCP citado','Primera fuente BCP','Bloque generativo AIO','URLs citadas','Tipo de dato'],...r.map(o=>[PROJECT.get(o.projectId).name,MODEL.get(o.modelId).name,promptMap.get(o.promptId).text,o.date,o.mentions??'',o.brandMentioned?'Sí':'No',o.brandCited?'Sí':'No',o.linkPosition??'',o.blockAppeared===null?'':o.blockAppeared?'Sí':'No',o.sources.map(s=>s.url).join(' | '),o.isExample?'Ejemplo':LIVE?'GEO Tracker (n8n)':'Métricas originales'])];download('BCP_GEO_Monitor_fuentes.xlsx',xlsx(rows));toast(`Excel exportado · ${r.length} registros · Filtros aplicados`)};
// Retained detail events call the updated renderers, keeping pagination, sorting,
// carousel, response dialogs, recommendations, fullscreen and export behavior.
function refresh(){state.page=1;renderFilters();renderRoute()}
document.addEventListener('click',e=>{const range=e.target.closest('[data-range]');if(range){e.preventDefault();e.stopImmediatePropagation();M.period=({'1m':'30','3m':'90','6m':'180'})[range.dataset.range];refresh()}},true);
document.addEventListener('click',e=>{const el=e.target.closest('button');if(el?.dataset.nav){go(el.dataset.nav);return}if(el?.dataset.openproject){go('detail',el.dataset.openproject);return}if(el?.id==='engineTrigger'){const menu=$('#engineMenu');menu.hidden=!menu.hidden;el.setAttribute('aria-expanded',!menu.hidden)}if(el?.id==='engineAll'){M.models=M.models.size===5?new Set():new Set(MON.models.map(m=>m.id));refresh();$('#engineMenu').hidden=false;$('#engineTrigger').setAttribute('aria-expanded','true')}if(!e.target.closest('.engine-filter')&&$('#engineMenu')){$('#engineMenu').hidden=true;$('#engineTrigger').setAttribute('aria-expanded','false')}});
document.addEventListener('change',e=>{if(e.target.dataset.engine){e.target.checked?M.models.add(e.target.dataset.engine):M.models.delete(e.target.dataset.engine);refresh();$('#engineMenu').hidden=false;$('#engineTrigger').setAttribute('aria-expanded','true')}if(e.target.id==='globalPeriod'){M.period=e.target.value;refresh()}if(e.target.id==='globalProject'){M.project=e.target.value;if(M.route==='detail'&&M.project==='all')M.route='dashboard';renderShell();renderRoute();history.replaceState(null,'',M.route==='detail'?'#proyecto/'+M.project:'#'+M.route)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#engineMenu')){$('#engineMenu').hidden=true;$('#engineTrigger').setAttribute('aria-expanded','false')}});
function readRoute(){const raw=location.hash.slice(1);if(raw.startsWith('proyecto/')&&PROJECT.has(raw.split('/')[1])){M.route='detail';M.project=raw.split('/')[1]}else if(['dashboard','projects','prompts','competitors','sources','settings'].includes(raw)){M.route=raw;M.project='all'}else M.route='dashboard';renderShell();renderRoute()}
window.addEventListener('popstate',readRoute);
// Initial route is rendered after the extensions below are registered.

function renderBrandHistory(){const el=$('#brandHistory');if(!el)return;const enabled=M.project==='marca'&&M.models.has('chatgpt')&&M.period==='180'&&(PROJECT.get('marca')?.promptIds||[]).every(id=>state.selected.has(id));const intro='<div class="dash-card-header"><div><h2>Evolución histórica por marca · ChatGPT</h2><p class="sub">Serie original · 27 abr a 8 jul 2026 · BCP y competidores</p></div></div>';if(!enabled){el.innerHTML=intro+'<p class="coverage-note">La serie original está disponible en «Últimos 6 meses» para el proyecto BCP Marca Chatgpt, con ChatGPT y todos sus prompts seleccionados.</p>';return}const ds=[...new Set(DATA.competitorSeries.map(o=>o.date))],W=800,H=230,L=38,T=12,B=30,R=15,x=i=>L+i*(W-L-R)/(ds.length-1),y=v=>T+(50-v)*(H-T-B)/50;let h=`<div class="monitor-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Serie original de Share of Voice de diez bancos en ChatGPT">`;for(let v=0;v<=50;v+=10)h+=`<path d="M${L} ${y(v)}H${W-R}" stroke="#EDF1F7"/><text x="${L-8}" y="${y(v)+3}" fill="#9AA9BF" text-anchor="end" font-size="9">${v}%</text>`;for(const b of DATA.currentRanking.items){if(!state.visible.has(b.brand))continue;const vals=ds.map(d=>DATA.competitorSeries.find(o=>o.brand===b.brand&&o.date===d)?.sov);if(vals.every(v=>v===undefined))continue;h+=`<polyline points="${vals.map((v,i)=>v===undefined?'':x(i)+','+y(v)).filter(Boolean).join(' ')}" fill="none" stroke="${b.color}" stroke-width="2"/>`;vals.forEach((v,i)=>{if(v!==undefined)h+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.6" fill="${b.color}"><title>${b.brand}: ${v}% · ${dateLabel(ds[i])}</title></circle>`})}ds.forEach((d,i)=>h+=`<text x="${x(i)}" y="${H-8}" fill="#9AA9BF" text-anchor="middle" font-size="8">${dateLabel(d)}</text>`);h+='</svg></div>';el.innerHTML=intro+h+'<div class="chart-legend">'+DATA.currentRanking.items.map(b=>`<span class="engine-badge"><span class="color-dot" style="background:${b.color}"></span>${esc(b.brand)}<button class="switch ${state.visible.has(b.brand)?'on':''}" role="switch" aria-checked="${state.visible.has(b.brand)}" aria-label="Mostrar ${esc(b.brand)}" data-brand="${esc(b.brand)}"></button></span>`).join('')+'</div><p class="chart-caption">Se conservan los ceros del 3 y 6 jul reportados en la fuente. No se incluyen series inexistentes.</p>'}

// Sources retain all cited domains; this filter selects responses citing BCP.
function sourceRows(){return observations().filter(o=>!M.sourcesBCP||(o.status!=='error'&&o.brandCited))}
function sourceFilter(){return `<div class="source-filter"><label><input id="sourceBCPOnly" type="checkbox" ${M.sourcesBCP?'checked':''}> Solo las que citan a BCP</label><span>Posición de la primera fuente de BCP según n8n.</span></div>`}
function categoryOf(o){return o.category||promptMap.get(o.promptId)?.category||'Sin categoría'}
function intentOf(o){return o.intent||promptMap.get(o.promptId)?.intent||'Sin intención'}
function segmentRows(){return observations().filter(o=>M.intent==='all'||intentOf(o)===M.intent)}
function segmentCategories(rows){const groups=new Map;for(const o of rows){const category=categoryOf(o);if(!groups.has(category))groups.set(category,[]);groups.get(category).push(o)}return [...groups].sort(([a],[b])=>a.localeCompare(b,'es'))}
function renderSegments(){
 const all=observations(),rows=segmentRows(),engines=MON.models.filter(m=>M.models.has(m.id));
 const intentions=[...new Set([...all.map(intentOf),...(M.intent==='all'?[]:[M.intent])])].sort((a,b)=>a.localeCompare(b,'es'));
 const groups=segmentCategories(rows);
 $('#view').innerHTML=`<div class="view-header"><div><h2>Segmentos por categoría</h2><p>Posición promedio, % de mención y Share of Voice de BCP por motor.</p></div><button class="button" id="exportSegments">${icon('download')}Exportar segmentos</button></div><div class="segment-toolbar"><label class="filter-control" for="segmentIntent">Intención<select id="segmentIntent"><option value="all">Todas las intenciones</option>${intentions.map(intent=>`<option value="${esc(intent)}" ${M.intent===intent?'selected':''}>${esc(intent)}</option>`).join('')}</select></label><span>${rows.length} observaciones · ${summary(rows).n} respuestas válidas</span></div>${groups.length&&engines.length?`<div class="card table-scroll"><table class="segment-table"><thead><tr><th rowspan="2" scope="col">Categoría</th>${engines.map(m=>`<th colspan="4" scope="colgroup">${engineBadge(m.id)}</th>`).join('')}</tr><tr>${engines.map(()=>'<th>Válidas</th><th>Posición promedio</th><th>% de mención</th><th>SoV</th>').join('')}</tr></thead><tbody>${groups.map(([category,rs])=>`<tr><th scope="row">${esc(category)}</th>${engines.map(m=>{const a=summary(rs.filter(o=>o.modelId===m.id));return `<td>${a.n}</td><td>${a.position===null?'—':'#'+fmt(a.position)}</td><td>${a.mentionRate===null?'—':fmt(a.mentionRate)+'%'}</td><td class="segment-sov">${a.som===null?'—':fmt(a.som)+'%'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="card">'+allEmpty('No hay observaciones para la intención y los motores seleccionados.')+'</div>'}<p class="coverage-note">Cada celda respeta el periodo, el proyecto y los motores seleccionados. Las respuestas con error no cuentan. La posición se promedia solo donde BCP aparece. El SoV usa el valor calculado por n8n.</p>`;
}
function exportSegments(){
 const engines=MON.models.filter(m=>M.models.has(m.id));
 const rows=[['BCP GEO Monitor · Segmentos'],['Proyecto','Categoría','Intención','Motor','Respuestas válidas','Posición promedio','% de mención','Share of Voice (%)'],...segmentCategories(segmentRows()).flatMap(([category,rs])=>engines.map(m=>{const a=summary(rs.filter(o=>o.modelId===m.id));return [PROJECT.get(M.project)?.name||'Todos los proyectos',category,M.intent==='all'?'Todas las intenciones':M.intent,m.name,a.n,a.position??'',a.mentionRate??'',a.som??'']}))];
 download('BCP_GEO_Monitor_segmentos.xlsx',xlsx(rows));toast('Segmentos exportados · Filtros aplicados');
}
metricSegment=function(current,group,history=false){return `<div class="segment light">${[['sov','Share of Voice'],['position','Posición'],['linkPosition','Pos. Enlace']].map(([k,v])=>`<button data-${group}="${k}" class="${current===k?'active':''}" aria-pressed="${current===k}">${v}</button>`).join('')}</div>`};
tabs.push('Segmentos');
render=function(){renderTabs();[renderPrompts,renderCompetitive,renderRecs,renderReferences,renderBI,renderSegments][state.tab]()};
document.addEventListener('change',e=>{
 if(e.target.id==='sourceBCPOnly'){M.sourcesBCP=e.target.checked;if(M.route==='detail')renderReferences();else renderSourcesPage()}
 if(e.target.id==='segmentIntent'){M.intent=e.target.value;renderSegments()}
});
document.addEventListener('click',e=>{if(e.target.closest('#exportSegments'))exportSegments()});
readRoute();
